/* =========================================================================
   FONTES OFICIAIS NOS PDFs (IBM Plex Sans + Guanabara Sans)
   -------------------------------------------------------------------------
   Subconjunto latino das fontes (gerado a partir de marca/fontes/, ver
   docs/FONTES.md), embutido em base64 para o jsPDF.
   prepararFontesPdf(doc) registra as fontes num documento novo e faz a troca
   automática:
     setFont('helvetica', estilo)      -> IBM Plex Sans (normal, negrito, itálico)
     negrito com tamanho >= 13 pt      -> Guanabara Sans Bold (títulos e números grandes)
   Assim os geradores de PDF continuam escrevendo setFont('helvetica',…) e, se
   algo falhar ao carregar as fontes, o PDF sai normalmente em Helvetica.
   ========================================================================= */
const FONTES_PDF={
  plexR:'',
  plexB:'',
  plexI:'',
  guaB:''
};
const PDF_TAM_TITULO=13;
function prepararFontesPdf(doc){
  try{
    doc.addFileToVFS('IBMPlexSans-Regular.ttf',FONTES_PDF.plexR);doc.addFont('IBMPlexSans-Regular.ttf','IBMPlexSans','normal');
    doc.addFileToVFS('IBMPlexSans-Bold.ttf',FONTES_PDF.plexB);doc.addFont('IBMPlexSans-Bold.ttf','IBMPlexSans','bold');
    doc.addFileToVFS('IBMPlexSans-Italic.ttf',FONTES_PDF.plexI);doc.addFont('IBMPlexSans-Italic.ttf','IBMPlexSans','italic');
    doc.addFileToVFS('GuanabaraSans-Bold.ttf',FONTES_PDF.guaB);doc.addFont('GuanabaraSans-Bold.ttf','GuanabaraSans','bold');
  }catch(e){console.warn('Fontes do PDF indisponíveis; usando Helvetica.',e);return doc;}
  const setFontOrig=doc.setFont.bind(doc),setSizeOrig=doc.setFontSize.bind(doc);
  let estilo='normal';
  const aplicar=()=>{
    const titulo=estilo==='bold'&&doc.getFontSize()>=PDF_TAM_TITULO;
    setFontOrig(titulo?'GuanabaraSans':'IBMPlexSans',titulo?'bold':estilo);
  };
  doc.setFont=(fam,st)=>{
    if(String(fam).toLowerCase()==='helvetica'){estilo=st==='bold'||st==='italic'?st:'normal';aplicar();return doc;}
    return setFontOrig(fam,st);
  };
  doc.setFontSize=sz=>{setSizeOrig(sz);const f=doc.getFont().fontName;if(f==='IBMPlexSans'||f==='GuanabaraSans')aplicar();return doc;};
  doc.setFont('helvetica','normal');
  return doc;
}
